use std::{fs::File,io::{Write,BufWriter}};
use nihav_core::codecs::{NADecoderSupport,RegisteredDecoders};
use nihav_core::demuxers::{RegisteredDemuxers,create_demuxer,DemuxerError};
use nihav_core::io::byteio::FileReader;
fn main(){let name=std::env::args().nth(1).unwrap();let output=std::env::args().nth(2);let mut file=File::open(name).unwrap();let mut br=FileReader::new_read(&mut file);let mut dmx_reg=RegisteredDemuxers::new();nihav_rad::rad_register_all_demuxers(&mut dmx_reg);let mut dmx=create_demuxer(dmx_reg.find_demuxer("bink").unwrap(),&mut br).unwrap();let mut reg=RegisteredDecoders::new();nihav_rad::rad_register_all_decoders(&mut reg);let info=dmx.get_stream(0).unwrap().get_info();let mut dec=reg.find_decoder(info.get_name()).unwrap()();let mut support=NADecoderSupport::new();dec.init(&mut support,info).unwrap();let mut count=0;let mut output=output.map(|p|BufWriter::new(File::create(p).unwrap()));loop{let packet=match dmx.get_frame(){Ok(p)=>p,Err(DemuxerError::EOF)=>break,Err(e)=>panic!("Demux {:?}",e)};match dec.decode(&mut support,&packet){Ok(frame)=>{count+=1;if let Some(ref mut out)=output{let data=frame.get_buffer().get_vbuf().unwrap();let(w,h)=data.get_dimensions(0);if count==1{out.write_all(b"NIH1").unwrap();out.write_all(&(w as u32).to_le_bytes()).unwrap();out.write_all(&(h as u32).to_le_bytes()).unwrap();}let pixels=data.get_data();for plane in 0..4{let(pw,ph)=data.get_dimensions(plane);let offset=data.get_offset(plane);let stride=data.get_stride(plane);for y in 0..ph{out.write_all(&pixels[offset+y*stride..offset+y*stride+pw]).unwrap();}}}println!("decoded {}",count)},Err(e)=>panic!("Frame{} {:?}",count+1,e)}}}
